const posts = [
  {
    title: "Ultimate Guide to visit Pamukkale – Turkey's Cotton Castles",
    image: "/images/pamukkale.jpg",
    href: "/blog/ultimate-guide-to-visit-pamukkale-turkeys-cotton-castles",
  },
  {
    title: "Facts about Mesopotamia: The Cradle Of Civilization",
    image: "/images/lion.jpg",
    href: "/blog/facts-about-mesopotamia-the-cradle-of-civilization",
  },
  {
    title: "5 Places You Have to See in Dubai & Things to do in Dubai in 2025",
    image: "/images/dubai.avif",
    href: "/blog/5-places-you-have-to-see-in-dubai-things-to-do-in-dubai-in-2023",
  },
];

export default function BlogTeasers() {
  return (
    <section className="tw-font-display tw-bg-[#14101c] tw-py-16 md:tw-py-20">
      <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
        <div className="tw-text-center tw-mb-10">
          <h2 className="tw-text-[clamp(28px,4vw,44px)] tw-font-bold tw-tracking-tight tw-text-white tw-uppercase tw-m-0">
            Days to come
          </h2>
          <p className="tw-mt-2 tw-mb-0 tw-text-[15px] tw-text-white/70">
            Final travel tips from our experts
          </p>
        </div>

        <div className="tw-grid tw-grid-cols-1 md:tw-grid-cols-3 tw-gap-5 lg:tw-gap-6">
          {posts.map((post) => (
            <a
              key={post.href}
              href={post.href}
              target="_blank"
              rel="noopener noreferrer"
              className="tw-group tw-relative tw-flex tw-min-h-[280px] tw-overflow-hidden tw-rounded-2xl tw-no-underline"
            >
              <img
                src={post.image}
                alt={post.title}
                loading="lazy"
                className="tw-absolute tw-inset-0 tw-h-full tw-w-full tw-object-cover tw-transition-transform tw-duration-500 group-hover:tw-scale-105"
              />
              <div
                className="tw-absolute tw-inset-0"
                style={{
                  background:
                    "linear-gradient(180deg, rgba(20,16,28,0.15) 0%, rgba(20,16,28,0.55) 55%, rgba(20,16,28,0.88) 100%)",
                }}
                aria-hidden="true"
              />
              <div className="tw-relative tw-mt-auto tw-p-6">
                <h3 className="tw-text-[18px] tw-font-bold tw-leading-snug tw-text-white tw-m-0">
                  {post.title}
                </h3>
                <span className="tw-mt-4 tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-border tw-border-solid tw-border-white/40 tw-px-4 tw-py-2 tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wide tw-text-white group-hover:tw-bg-white group-hover:tw-text-[#14101c] tw-transition-colors">
                  Read more <span aria-hidden="true">→</span>
                </span>
              </div>
            </a>
          ))}
        </div>
      </div>
    </section>
  );
}
